const agendas = [
 {title:'What colour should the bike shed be?',description:'The shed needs paint. Someone has already bought a perfectly good tin of blue.',proposal:'“Let’s paint it blue and get back to our projects.”',choices:[['Request seventeen more paint swatches.',18,90,-16,'The room discovers that “blue” is an offensively imprecise specification.'],['Establish a colour selection working group.',32,150,-25,'A subcommittee is formed. Its first task is choosing a name.'],['Agree on blue. Debate the finish instead.',10,45,9,'Everyone enjoys this refreshing compromise. Matte versus eggshell remains unresolved.']]},
 {title:'The label maker needs a label.',description:'Nobody can find the label maker. It is on the shelf marked “miscellaneous.”',proposal:'“Put a label on the shelf that says label maker.”',choices:[['Debate whether “labelmaker” is one word.',16,85,-14,'Three dictionaries enter the conversation. None leaves unscathed.'],['Propose a recursive labelling standard.',29,145,-24,'Who labels the label that labels the label maker? A compelling question.'],['Write “label maker” on masking tape.',7,30,12,'A practical solution! Someone quietly adds the tape to the next agenda.']]},
 {title:'A mug has been in the sink for six weeks.',description:'It may belong to someone. It may now be someone. Nobody wants to touch it.',proposal:'“Wash the mug.”',choices:[['Draft a comprehensive mug ownership policy.',24,120,-21,'The document is now longer than the lease. The mug remains unwashed.'],['Discuss whether it qualifies as a project.',19,95,-16,'It has grown substantially, so technically there has been progress.'],['Suggest a five-minute dishwashing recess.',8,35,11,'The room returns happier. Someone washed a different mug.']]},
 {title:'How should we sort the spare bolts?',description:'There are nine coffee tins, fourteen sizes, and a surprising number of opinions.',proposal:'“Metric on the left. Imperial on the right.”',choices:[['Sort by emotional significance.',20,110,-18,'One M8 bolt is described as “deeply formative.” Nobody asks.'],['Reopen the metric-versus-imperial debate.',35,180,-29,'Someone says “freedom units.” The chair takes a very long breath.'],['Start with a bin labelled “bolts, probably.”',8,40,10,'A broad consensus emerges around the word “probably.”']]},
 {title:'The shop playlist needs a decision.',description:'One speaker. Twelve makers. Seven incompatible definitions of “background music.”',proposal:'“Keep the volume low and take turns.”',choices:[['Define an acceptable beats-per-minute policy.',23,120,-20,'An exception for lathe operation requires another discussion.'],['Give every genre proportional representation.',31,165,-27,'Progressive metal demands an extra seventeen minutes per track.'],['Observe a minute of contemplative silence.',6,25,13,'For sixty beautiful seconds, nobody offers an opinion. Then someone does.']]},
 {title:'What counts as a “temporary” project?',description:'A half-built contraption has occupied a table since a calendar year nobody wishes to name.',proposal:'“Ask the owner to move it this week.”',choices:[['Define “temporary” in geological terms.',25,135,-22,'Against the age of the Earth, the project has barely arrived.'],['Commission a historical occupancy survey.',30,155,-25,'The oldest photograph shows the same table. The plot thickens.'],['Give it a friendly reminder sticky note.',9,40,10,'The note is universally praised. Its precise placement is deferred.']]},
 {title:'The new committee needs a name.',description:'Its purpose is to reduce the number of committees. The irony has been minuted.',proposal:'“Call it the committee review group.”',choices:[['Spend half an hour making an acronym.',30,160,-26,'The best option spells SHED. Nobody remembers what the letters mean.'],['Create a committee naming subcommittee.',26,140,-23,'Membership is open. Scope, mandate, and snacks are all disputed.'],['Use a working title. Under protest.',8,35,11,'The working title is “Working Title.” This feels like progress. It is not.']]},
 {title:'When should we have the next meeting?',description:'At last, the final item. There is only one thing standing between everyone and actual making.',proposal:'“Same time next month?”',choices:[['Compare everyone’s calendars, out loud.',28,150,-23,'Conflicts include a dentist appointment, a maybe, and a philosophical objection.'],['Debate whether meetings are even necessary.',40,220,-32,'The meeting votes to discuss abolishing meetings at the next meeting.'],['Same time. Bring snacks.',9,45,10,'A unanimous vote! For the snacks. The date is still provisional.']]}
];
let state; const $=id=>document.getElementById(id);
function reset(){state={round:0,time:0,score:0,patience:100,picked:false,ended:false};$('play').hidden=false;$('result').hidden=true;$('log').innerHTML='<li>The meeting was called to order. A mistake, in retrospect.</li>';render();}
function render(){const a=agendas[state.round];$('round').textContent=`ITEM ${String(state.round+1).padStart(2,'0')} / 08`;$('topic-number').textContent=String(state.round+1).padStart(2,'0');$('topic').textContent=a.title;$('description').textContent=a.description;$('proposal').textContent=a.proposal;$('feedback').hidden=true;$('next').hidden=true;$('choices').replaceChildren();a.choices.forEach((c,i)=>{let b=document.createElement('button');b.className='choice';b.innerHTML=`<span class="choice-num">${i+1}</span><span><span class="choice-title">${c[0]}</span><span class="effect">+${c[1]} min · +${c[2]} pts · ${c[3]>0?'+':''}${c[3]}% patience</span></span><span class="choice-arrow">↗</span>`;b.onclick=()=>choose(i);$('choices').append(b)});metrics();}
function metrics(){$('time').innerHTML=`${state.time}<span> min</span>`;$('score').textContent=state.score;$('patience').innerHTML=`${state.patience}<span>%</span>`;$('patience-bar').style.width=state.patience+'%';$('patience-bar').style.background=state.patience<30?'#f45125':'#aac578';$('duration').textContent=state.time?`ACTUAL: ${state.time} MINUTES.`:"ACTUAL: WE'LL SEE.";}
function choose(i){if(state.picked||state.ended)return;state.picked=true;const c=agendas[state.round].choices[i];state.time+=c[1];state.score+=c[2];state.patience=Math.max(0,Math.min(100,state.patience+c[3]));[...$('choices').children].forEach((b,n)=>{b.disabled=true;if(n===i)b.classList.add('selected')});$('feedback').textContent=c[4];$('feedback').hidden=false;const item=document.createElement('li');item.textContent=`${state.time} min — ${c[4]}`;$('log').prepend(item);metrics();$('next').hidden=false;$('next').innerHTML=state.patience===0||state.round===7?'Adjourn the meeting <span>→</span>':'Next agenda item <span>→</span>';$('next').focus({preventScroll:true});}
function next(){if(!state.picked||state.ended)return;if(state.patience===0||state.round===7){end();return}state.round++;state.picked=false;render();$('choices').firstChild.focus({preventScroll:true});}
function end(){state.ended=true;const survived=state.patience>0;const bonus=survived?state.patience*2:0;state.score+=bonus;metrics();$('play').hidden=true;$('result').hidden=false;$('round').textContent='MEETING CLOSED';$('result-title').textContent=!survived?'You have lost quorum.':state.score>=1000?'A master of pointless debate.':state.score>=750?'Certified bikeshed architect.':'Suspiciously reasonable.';$('result-description').textContent=survived?`You survived all eight agenda items and wasted ${state.time} minutes. ${bonus} bonus points for keeping the room together. The bike shed is still unpainted.`:`After ${state.time} minutes and ${state.round+1} agenda items, the last patient member went home. Your motions were magnificent. Your people skills need work.`;$('final-score').textContent=state.score;$('restart').focus({preventScroll:true});}
$('next').onclick=next;$('restart').onclick=reset;$('rules').onclick=()=>$('help').showModal();$('close-help').onclick=$('got-it').onclick=()=>$('help').close();$('help').addEventListener('click',e=>{if(e.target===$('help')){const r=$('help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('help').close();}});document.addEventListener('keydown',e=>{if($('help').open||e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;if(['1','2','3'].includes(e.key)){e.preventDefault();choose(Number(e.key)-1)}if(e.key==='Enter'&&state.picked&&!state.ended&&document.activeElement?.tagName!=='BUTTON'){e.preventDefault();next()}});reset();
